import { createErrorRegistry } from "@superfunctions/errors";
import { err as createEnvelopeError, ok as createEnvelopeSuccess, toLegacyResultEnvelope } from "@superfunctions/envelope";
import type { CmsfnError, CmsfnErrorCode } from "./errors.js";

export type CmsfnEnvelope<T> =
  | { ok: true; result: T }
  | { ok: false; error: CmsfnError };

const cmsErrorRegistry = createErrorRegistry([
  { code: "AUTH_REQUIRED", httpStatus: 401, retryable: false },
  { code: "PERMISSION_DENIED", httpStatus: 403, retryable: false },
  { code: "VALIDATION_FAILED", httpStatus: 400, retryable: false },
  { code: "PAYLOAD_TOO_LARGE", httpStatus: 413, retryable: false },
  { code: "RATE_LIMITED", httpStatus: 429, retryable: true },
  { code: "NOT_FOUND", httpStatus: 404, retryable: false },
  { code: "CONFLICT", httpStatus: 409, retryable: false },
  { code: "PREVIEW_NOT_CONFIGURED", httpStatus: 400, retryable: false },
  { code: "CONTENTFN_UNAVAILABLE", httpStatus: 503, retryable: true },
  { code: "INTERNAL_ERROR", httpStatus: 500, retryable: true },
]);

export function ok<T>(result: T): { ok: true; result: T } {
  const canonical = createEnvelopeSuccess(result);
  const legacy = toLegacyResultEnvelope(canonical);
  if (!legacy.ok) {
    throw new Error("Expected a successful CMS envelope");
  }
  return legacy;
}

export function err<T = never>(
  code: CmsfnErrorCode,
  message: string,
  details: CmsfnError["details"] = {}
): { ok: false; error: CmsfnError } {
  const resolved = cmsErrorRegistry.resolveOrDefault(code, {
    httpStatus: 500,
    retryable: code === "INTERNAL_ERROR" || code === "CONTENTFN_UNAVAILABLE" || code === "RATE_LIMITED",
  });
  const canonical = createEnvelopeError({
    code,
    message,
    status: resolved.httpStatus,
    retryable: resolved.retryable,
    details: { ...details },
  });

  return {
    ok: false,
    error: {
      code: canonical.error.code as CmsfnErrorCode,
      message: canonical.error.message,
      details: (canonical.error.details ?? {}) as CmsfnError["details"],
    },
  };
}
/**
 * Structured logging with redaction: no raw document bodies, no asset bytes, no auth secrets.
 * OBS-001: logs contain action metadata only.
 */

export interface LogMutationInput {
  action: string;
  dataset?: string;
  docId?: string;
  /** Must NOT be logged (redacted). */
  body?: unknown;
}

export interface LogAuthInput {
  action: string;
  subject?: string;
  /** Must NOT be logged (redacted). */
  token?: string;
  /** Must NOT be logged (redacted). */
  password?: string;
}

export type LogSink = (level: string, message: string, meta: Record<string, unknown>) => void;

/** Never log these keys; omit entirely. */
const SENSITIVE_KEYS = new Set(["body", "token", "password", "secret", "authorization"]);

function safeMeta<T extends Record<string, unknown>>(input: T): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(input)) {
    if (v !== undefined && !SENSITIVE_KEYS.has(k)) out[k] = v;
  }
  return out;
}

export interface CmsfnLoggerConfig {
  sink?: LogSink;
}

const defaultSink: LogSink = (level, message, meta) => {
  const line = JSON.stringify({ level, message, ...meta });
  if (level === "error") {
    console.error(line);
  } else {
    console.log(line);
  }
};

/**
 * Create a logger that never logs body, token, password, or other sensitive fields.
 */
export function createLogger(config: CmsfnLoggerConfig = {}): {
  logMutation: (input: LogMutationInput) => void;
  logAuth: (input: LogAuthInput) => void;
} {
  const sink = config.sink ?? defaultSink;

  return {
    logMutation(input: LogMutationInput) {
      const meta = safeMeta(input as Record<string, unknown>);
      sink("info", "mutation", meta);
    },

    logAuth(input: LogAuthInput) {
      const meta = safeMeta(input as Record<string, unknown>);
      sink("info", "auth", meta);
    },
  };
}
