    const event = { eventId: "e1", dataset: "prod", type: "doc.published", timestamp: "2026-10-22T00:00:00Z", document: { _id: "post", _type: "post", body: "private" }, actor: { subject: "user", secret: "private" }, diff: { changedPaths: ["title"], rawBody: "private" } };
    reply({ ok: true, result: { events: [event], nextCursor: null } });
    expect(await contentfnAuditEvents({ contentfnBaseUrl: base }, { dataset: "prod" })).toEqual({ ok: true, result: { events: [{ ...event, document: { _id: "post", _type: "post" }, actor: { subject: "user" }, diff: { changedPaths: ["title"] } }], nextCursor: null } });
    for (const bad of [{ ...event, dataset: "other" }, { ...event, document: { _id: 1, _type: "post" } }, { ...event, actor: { subject: [] } }, { ...event, diff: { changedPaths: [1] } }]) {
      reply({ ok: true, result: { events: [bad], nextCursor: null } });
      expect(await contentfnAuditEvents({ contentfnBaseUrl: base }, { dataset: "prod" })).toMatchObject({ ok: false });
    }
    const delivery = { webhookId: "w1", dataset: "prod", url: "https://example.invalid", eventId: "e1", attempt: 1, status: "delivered", updatedAt: "2026-10-22T00:00:00Z" };
    for (const bad of [{ ...delivery, status: "invented" }, { ...delivery, attempt: -1 }, { ...delivery, dataset: "other" }]) {
      reply({ ok: true, result: { deliveries: [bad], nextCursor: null } });
      expect(await contentfnAuditWebhooks({ contentfnBaseUrl: base }, { dataset: "prod" })).toMatchObject({ ok: false });
    }
  }));
});
