/**
 * Structured log event matching v0 spec
 */
export interface LogEvent {
  /** RFC3339 timestamp with milliseconds */
  ts: string;

  /** Log severity level */
  level: LogLevel;

  /** Human-readable message */
  msg: string;

  /** Logger/component name */
  name: string;

  /** Arbitrary context (shallow serializable values only) */
  ctx?: Record<string, unknown>;

  /** Tags for categorization (<= 20 entries) */
  tags?: string[];

  /** W3C TraceContext trace ID */
  traceId?: string;

  /** W3C TraceContext span ID */
  spanId?: string;

  /** Request correlation ID */
  requestId?: string;

  /** User identifier (may be redacted) */
  userId?: string;

  /** Tenant identifier (may be redacted) */
  tenantId?: string;

  /** Schema version */
  version: string;
}

