import { createHash } from 'node:crypto';
/** Bounds apply to serialized UTF-8 events, independently of execution status. */
export const LOG_BATCH_BYTES = 64 * 1024;
export const LOG_JOB_BYTES = 1024 * 1024;
export const LOG_MAX_EVENTS = 4096;
export const LOG_RETENTION_MS = 7 * 24 * 60 * 60 * 1000;
export type LogTransferStatus = 'pending' | 'complete' | 'truncated' | 'failed' | 'expired';
/** Actual LogFn envelope subset used by Ci's private durable sink. */
export interface RunnerLogEvent { ts: string; level: 'info'; name: 'cifn'; msg: string; version: string; ctx: { stepKey: string } }
export interface LogPacket { sequence: number; events: RunnerLogEvent[]; terminal?: 'complete' | 'truncated' | 'failed'; digest: string }
export interface LogLedger { status: LogTransferStatus; expiresAt: number; bytes: number; eventCount: number; packets: LogPacket[] }
export function logDigest(value: Omit<LogPacket, 'digest'>): string {
  return createHash('sha256').update(JSON.stringify({ sequence: value.sequence, events: value.events, ...(value.terminal ? { terminal: value.terminal } : {}) })).digest('hex');
}
export function validateLogPacket(value: unknown): value is LogPacket {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const p = value as LogPacket;
  if (Object.keys(p).some(key => !['sequence', 'events', 'terminal', 'digest'].includes(key)) ||
    !Number.isSafeInteger(p.sequence) || p.sequence < 0 || p.sequence > LOG_MAX_EVENTS ||
    typeof p.digest !== 'string' || !/^[a-f0-9]{64}$/.test(p.digest) || !Array.isArray(p.events) || p.events.length > 128 ||
    (p.terminal !== undefined && !['complete', 'truncated', 'failed'].includes(p.terminal)) || (!p.terminal && p.events.length === 0)) return false;
  for (const event of p.events) {
    if (!event || typeof event !== 'object' || Object.keys(event).sort().join(',') !== 'ctx,level,msg,name,ts,version' ||
      typeof event.ts !== 'string' || !Number.isFinite(Date.parse(event.ts)) || event.ts.length > 32 || event.level !== 'info' || event.name !== 'cifn' ||
      typeof event.msg !== 'string' || Buffer.byteLength(event.msg) > 8192 || typeof event.version !== 'string' || event.version.length > 16 ||
      !event.ctx || typeof event.ctx !== 'object' || Object.keys(event.ctx).join(',') !== 'stepKey' || typeof event.ctx.stepKey !== 'string' || event.ctx.stepKey.length > 128) return false;
  }
  return Buffer.byteLength(JSON.stringify(p.events)) <= LOG_BATCH_BYTES && p.digest === logDigest(p);
}
import { spawn } from 'node:child_process';
import { StringDecoder } from 'node:string_decoder';
import { setTimeout as delay } from 'node:timers/promises';
import type { RunStepResult } from './run-step.js';

export class ProcessGroupUncertainError extends Error {
  constructor() { super('Owned process group termination requires reconciliation'); }
}
/** POSIX only. Never uses process identities recovered from persistent state. */
export async function executeOwnedShell(command: string, cwd: string, env: NodeJS.ProcessEnv, signal?: AbortSignal): Promise<RunStepResult> {
  const empty = { exitCode: 1, stdout: '', stderr: '', lines: [] };
  if (signal?.aborted) return empty;
  if (process.platform === 'win32') throw new ProcessGroupUncertainError();
  const child = spawn('/bin/sh', ['-c', command], { cwd, env, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
  let closed = false;
  child.once('close', () => { closed = true; });
  let stdout = ''; let stderr = ''; let bytes = 0; let stopping = false;
  const stdoutDecoder = new StringDecoder('utf8');
  const stderrDecoder = new StringDecoder('utf8');
  const alive = () => {
    if (!child.pid) return false;
    try { process.kill(-child.pid, 0); return true; }
    catch (cause) { if ((cause as NodeJS.ErrnoException).code === 'ESRCH') return false;
      // A transient EPERM probe is not proof of disappearance. Keep waiting
      // within the existing deadline; signal-delivery errors still fail closed.
      if ((cause as NodeJS.ErrnoException).code === 'EPERM') return true;
      throw new ProcessGroupUncertainError(); }
  };
  const send = (value: NodeJS.Signals) => {
    if (!child.pid) return;
    try { process.kill(-child.pid, value); }
    catch (cause) { if ((cause as NodeJS.ErrnoException).code !== 'ESRCH') throw new ProcessGroupUncertainError(); }
  };
  let termination: Promise<void> | undefined;
  let rejectTermination!: (cause: unknown) => void;
  const terminationFailure = new Promise<number>((_, reject) => { rejectTermination = reject; });
  void terminationFailure.catch(() => {});
  const stop = () => {
    stopping = true;
    if (!termination) {
      termination = (async () => {
        send('SIGTERM');
        const gracefulUntil = Date.now() + 1_000;
        while (alive() && Date.now() < gracefulUntil) await delay(20);
        if (alive()) send('SIGKILL');
        const killUntil = Date.now() + 5_000;
        while (alive() && Date.now() < killUntil) await delay(20);
        if (alive()) throw new ProcessGroupUncertainError();
      })();
      // Observed again below; suppress unhandled rejection while awaiting child exit.
      void termination.catch(rejectTermination);
    }
  };
  const capture = (chunk: Buffer, output: 'stdout' | 'stderr') => {
    bytes += chunk.length;
    if (bytes > 1_048_576) { stop(); return; }
    if (output === 'stdout') stdout += stdoutDecoder.write(chunk); else stderr += stderrDecoder.write(chunk);
  };
  child.stdout.on('data', chunk => capture(chunk, 'stdout'));
  child.stderr.on('data', chunk => capture(chunk, 'stderr'));
  signal?.addEventListener('abort', stop, { once: true });
  const timeout = setTimeout(stop, 300_000);
  try {
    const exited = new Promise<number>(resolve => {
      child.once('error', () => resolve(1));
      child.once('exit', (code) => resolve(code ?? 1));
      if (signal?.aborted) stop();
    });
    const code = await Promise.race([exited, terminationFailure]);
    // A shell exit or closed stdio does not prove its descendants have exited.
    if (alive()) stop();
    if (termination) await termination;
    if (alive()) throw new ProcessGroupUncertainError();
    const streamsUntil = Date.now() + 1_000;
    while (!closed && Date.now() < streamsUntil) await delay(10);
    if (!closed) throw new ProcessGroupUncertainError();
    stdout += stdoutDecoder.end(); stderr += stderrDecoder.end();
    // A forcibly interrupted capture may end in a secret prefix. Withhold the
    // entire partial step output instead of persisting an unredactable fragment.
    if (stopping) return { exitCode: 1, stdout: '', stderr: '', lines: [], truncated: true };
    const lines = [...stdout.split('\n'), ...stderr.split('\n')].filter(Boolean);
    return { exitCode: stopping ? 1 : code, stdout, stderr, lines };
  } finally {
    clearTimeout(timeout); signal?.removeEventListener('abort', stop);
    child.stdout.destroy(); child.stderr.destroy();
  }
}

