p='watchfn/typescript/src/alerts/alert-manager.ts';s=open(p).read();s=s.replace("  update(id: string, input: AlertConfig) { const config = this.validate(input); return this.host.admit(() => this.mutate(id, record => { Object.assign(record, config, { enabled: config.enabled ?? record.enabled }); })); }", """  update(id: string, input: AlertConfig) {
    const config = this.validate(input);
    return this.host.admit(() => this.mutate(id, record => {
      // A full definition replacement must remove omitted recovery/routing metadata.
